new_helpers = '''def prefix_match_mask(values: np.ndarray, prefix: str) -> np.ndarray:
    """Vectorised ``str(value).startswith(prefix)`` over canonical spellings.

    Canonical decimal spellings carry no sign and no leading zero, so a value of
    ``digits`` decimal digits starts with ``prefix`` exactly when the leading
    ``len(prefix)`` digits equal ``int(prefix)``.  Grouping values by digit
    length keeps this a handful of vector comparisons instead of string work.
    """
    if values.size == 0:
        return np.zeros(0, dtype=bool)
    if not prefix:
        return np.ones(values.size, dtype=bool)
    target = int(prefix)
    length = len(prefix)
    match = np.zeros(values.size, dtype=bool)
    for digits in range(1, 8):
        if digits < length:
            continue
        low = 0 if digits == 1 else 10 ** (digits - 1)
        high = 9 if digits == 1 else 10 ** digits - 1
        selected = (values >= low) & (values <= high)
        match |= selected & ((values // 10 ** (digits - length)) == target)
    return match


def _spelling_exists(values: np.ndarray, prefix: str) -> bool:
    """Does any value have a canonical decimal spelling with this prefix?"""
    return bool(prefix_match_mask(values, prefix).any())


